import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long t = nextLong();
            // lower_bound: first index whose value is >= t.
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (a[mid] < t) lo = mid + 1;
                else hi = mid;
            }
            long p = lo;
            // Elements before p are raised to t, the rest are lowered to t.
            long cost = t * p - prefix[lo] + (prefix[n] - prefix[lo]) - t * (n - p);
            sb.append(cost).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + a[i]
	}
	var out []byte
	for k := 0; k < q; k++ {
		t := nextInt()
		// Elements before p are raised to t, the rest are lowered to t.
		p, _ := slices.BinarySearch(a, t)
		cost := t*int64(p) - prefix[p] + (prefix[n] - prefix[p]) - t*int64(n-p)
		out = strconv.AppendInt(out, cost, 10)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
